#include <algorithm>
#include <map>
#include <optional>
#include <string>
#include <utility>

using Handle = int;
constexpr Handle INVALID = -1;
inline std::map<std::string, std::string> g_files;
inline std::map<Handle, std::pair<std::string, std::size_t>> g_open;
inline Handle g_nextHandle{ 3 };
inline int g_failOnRead{ 0 };
inline int g_reads{ 0 };
inline std::size_t g_chunk{ 5 };

Handle fakeOpen(const std::string& name)
{
    if (!g_files.count(name)) return INVALID;
    const Handle h{ g_nextHandle++ };
    g_open[h] = { name, 0 };
    g_reads = 0;
    return h;
}

long fakeRead(Handle h, char* buffer, std::size_t size)
{
    const auto it{ g_open.find(h) };
    if (it == g_open.end()) return -1;
    if (++g_reads == g_failOnRead) return -1;
    const std::string& data{ g_files[it->second.first] };
    const std::size_t pos{ it->second.second };
    const std::size_t n{ std::min({ size, g_chunk, data.size() - pos }) };
    std::copy_n(data.data() + pos, n, buffer);
    it->second.second += n;
    return static_cast<long>(n);
}

void fakeClose(Handle h) { g_open.erase(h); }

class File
{
public:
    explicit File(Handle h) : h_{ h } {}
    ~File() { if (h_ != INVALID) fakeClose(h_); }
    File(const File&) = delete;
    File& operator=(const File&) = delete;
    Handle get() const { return h_; }

private:
    Handle h_;
};

std::optional<std::string> readWholeFile(const std::string& name)
{
    File file{ fakeOpen(name) };
    if (file.get() == INVALID) return std::nullopt;
    std::string contents;
    char buffer[4096];
    for (;;)
    {
        const long n{ fakeRead(file.get(), buffer, sizeof buffer) };
        if (n < 0) return std::nullopt;
        if (n == 0) return contents;
        contents.append(buffer, static_cast<std::size_t>(n));
    }
}

std::optional<std::size_t> countLines(const std::string& name)
{
    const auto text{ readWholeFile(name) };
    if (!text) return std::nullopt;
    std::size_t lines{ static_cast<std::size_t>(std::count(text->begin(), text->end(), '\n')) };
    if (!text->empty() && text->back() != '\n') ++lines;
    return lines;
}

unitTests:
void setUp() { g_files.clear(); g_open.clear(); g_failOnRead = 0; g_chunk = 5; }
TEST("reading a file in several pieces") {
    setUp();
    g_files["notes.txt"] = "line one\nline two\nend";
    CHECK(readWholeFile("notes.txt") == std::optional<std::string>{ "line one\nline two\nend" });
    CHECK(g_open.empty());
}
TEST("a file longer than any buffer") {
    setUp();
    std::string big;
    for (int i{ 0 }; i < 3000; ++i) big += static_cast<char>('a' + i % 26);
    g_files["big.bin"] = big;
    g_chunk = 1000;
    CHECK(readWholeFile("big.bin") == std::optional<std::string>{ big });
    g_chunk = 100000;
    big += big + big;
    g_files["big.bin"] = big;
    CHECK(readWholeFile("big.bin") == std::optional<std::string>{ big });
    CHECK(g_open.empty());
}
TEST("empty and missing files") {
    setUp();
    g_files["empty"] = "";
    CHECK(readWholeFile("empty") == std::optional<std::string>{ "" });
    CHECK(!readWholeFile("missing").has_value());
    CHECK(g_open.empty());
}
TEST("a read that fails part way") {
    setUp();
    g_files["flaky"] = "0123456789abcdefghij";
    g_failOnRead = 3;
    CHECK(!readWholeFile("flaky").has_value());
    CHECK(g_open.empty());
    g_failOnRead = 1;
    CHECK(!readWholeFile("flaky").has_value());
    CHECK(g_open.empty());
}
TEST("counting lines") {
    setUp();
    g_files["a"] = "one\ntwo\nthree";
    g_files["b"] = "one\ntwo\n";
    g_files["c"] = "";
    g_files["d"] = "\n\n";
    CHECK(countLines("a") == std::optional<std::size_t>{ 3 });
    CHECK(countLines("b") == std::optional<std::size_t>{ 2 });
    CHECK(countLines("c") == std::optional<std::size_t>{ 0 });
    CHECK(countLines("d") == std::optional<std::size_t>{ 2 });
    CHECK(!countLines("nope").has_value());
    g_failOnRead = 2;
    CHECK(!countLines("a").has_value());
    CHECK(g_open.empty());
}

